PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL,institution TEXT NOT NULL DEFAULT '',opening_balance INTEGER NOT NULL,opening_date TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_id,id));
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('income','expense')),color TEXT NOT NULL,UNIQUE(owner_id,id));
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,last_four TEXT NOT NULL,credit_limit INTEGER NOT NULL CHECK(credit_limit>0),closing_day INTEGER NOT NULL CHECK(closing_day BETWEEN 1 AND 31),due_day INTEGER NOT NULL CHECK(due_day BETWEEN 1 AND 31),UNIQUE(owner_id,id));
CREATE TABLE IF NOT EXISTS subscriptions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),account_id TEXT NOT NULL,category_id TEXT NOT NULL,frequency TEXT NOT NULL CHECK(frequency IN ('monthly','yearly','weekly')),next_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','paused','cancelled')),kind TEXT NOT NULL DEFAULT 'expense' CHECK(kind IN ('income','expense')),anchor_day INTEGER NOT NULL DEFAULT 1,UNIQUE(owner_id,id),FOREIGN KEY(owner_id,account_id) REFERENCES accounts(owner_id,id),FOREIGN KEY(owner_id,category_id) REFERENCES categories(owner_id,id));
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer')),status TEXT NOT NULL CHECK(status IN ('settled','pending')),account_id TEXT NOT NULL,destination_id TEXT,category_id TEXT,date TEXT NOT NULL,time TEXT NOT NULL DEFAULT '12:00',notes TEXT NOT NULL DEFAULT '',subscription_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_id,id),UNIQUE(owner_id,subscription_id,date),CHECK(kind!='transfer' OR (destination_id IS NOT NULL AND destination_id!=account_id)),FOREIGN KEY(owner_id,account_id) REFERENCES accounts(owner_id,id),FOREIGN KEY(owner_id,destination_id) REFERENCES accounts(owner_id,id),FOREIGN KEY(owner_id,category_id) REFERENCES categories(owner_id,id),FOREIGN KEY(owner_id,subscription_id) REFERENCES subscriptions(owner_id,id));
CREATE TABLE IF NOT EXISTS purchases(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL,category_id TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),date TEXT NOT NULL,count INTEGER NOT NULL CHECK(count BETWEEN 1 AND 360),UNIQUE(owner_id,id),FOREIGN KEY(owner_id,card_id) REFERENCES cards(owner_id,id),FOREIGN KEY(owner_id,category_id) REFERENCES categories(owner_id,id));
CREATE TABLE IF NOT EXISTS installments(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purchase_id TEXT NOT NULL,card_id TEXT NOT NULL,category_id TEXT NOT NULL,number INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),due_date TEXT NOT NULL,UNIQUE(owner_id,purchase_id,number),FOREIGN KEY(owner_id,purchase_id) REFERENCES purchases(owner_id,id) ON DELETE CASCADE,FOREIGN KEY(owner_id,card_id) REFERENCES cards(owner_id,id),FOREIGN KEY(owner_id,category_id) REFERENCES categories(owner_id,id));
CREATE TABLE IF NOT EXISTS invoice_payments(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL,account_id TEXT NOT NULL,month TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),date TEXT NOT NULL,FOREIGN KEY(owner_id,card_id) REFERENCES cards(owner_id,id),FOREIGN KEY(owner_id,account_id) REFERENCES accounts(owner_id,id));
CREATE TABLE IF NOT EXISTS budgets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,month TEXT NOT NULL,category_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),attention INTEGER NOT NULL DEFAULT 70,near_limit INTEGER NOT NULL DEFAULT 90,CHECK(attention>0 AND attention<near_limit AND near_limit<100),UNIQUE(owner_id,month,category_id),FOREIGN KEY(owner_id,category_id) REFERENCES categories(owner_id,id));
CREATE TABLE IF NOT EXISTS goals(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',target INTEGER NOT NULL CHECK(target>0),desired_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','completed','archived')),kind TEXT NOT NULL CHECK(kind IN ('virtual','segregated')),account_id TEXT,UNIQUE(owner_id,id),CHECK(kind!='segregated' OR account_id IS NOT NULL),FOREIGN KEY(owner_id,account_id) REFERENCES accounts(owner_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS goal_account_unique ON goals(owner_id,account_id) WHERE kind='segregated';
CREATE TABLE IF NOT EXISTS contributions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,goal_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount!=0),date TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',FOREIGN KEY(owner_id,goal_id) REFERENCES goals(owner_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS liabilities(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(owner_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,onboarding_step INTEGER NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'BRL',timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo');
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,message TEXT NOT NULL,read_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mutation_requests(owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,key TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(owner_id,key));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,action TEXT NOT NULL,entity_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS transaction_owner_date ON transactions(owner_id,date);
CREATE INDEX IF NOT EXISTS transaction_owner_account ON transactions(owner_id,account_id,date);
CREATE INDEX IF NOT EXISTS installment_owner_date ON installments(owner_id,due_date);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires_at);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
